export const PHRASES = P;

const INDEX: Record<Exclude<Locale, "en">, 0 | 1 | 2> = { es: 0, de: 1, ja: 2 };

/** The phrase in the member's language, or the English text when there is no translation. */
export function phrase(locale: Locale, text: string): string {
  if (locale === "en") return text;
  return P[text]?.[INDEX[locale]] ?? text;
}
